import"./chunk-VC46IEJQ.js";var e=(t,s,n,r,a)=>({name:t,desc:s,tour:n,source:r,...a?{spoiler:a}:{}}),o={id:"pentos",intro:{en:"A merchant city of brick towers and tiled roofs on the Bay of Pentos, the Free City nearest Westeros. Its Prince is chosen from the old families and is largely ceremonial; the wealthy magisters hold the real power.",zh:"\u6F58\u6258\u65AF\u5750\u843D\u5728\u6F58\u6258\u65AF\u6E7E\u7554\uFF0C\u7816\u5854\u6797\u7ACB\u3001\u74E6\u9876\u8FDE\u7EF5\uFF0C\u662F\u79BB\u7EF4\u65AF\u7279\u6D1B\u6700\u8FD1\u7684\u81EA\u7531\u8D38\u6613\u57CE\u90A6\u3002\u4EB2\u738B\u4ECE\u53E4\u8001\u5BB6\u65CF\u4E2D\u63A8\u9009\uFF0C\u591A\u4E3A\u865A\u8854\uFF1B\u5B9E\u6743\u63E1\u5728\u5BCC\u6709\u7684\u603B\u7763\u4EEC\u624B\u4E2D\u3002"},notes:{en:"From the novels: square brick towers, walled manses such as Illyrio's, red priests and their night fires, a Prince chosen from the old families. From TWOIAF and wiki summaries: high but weakly defended walls, the Sunrise Gate to the east, bazaars, the Velvet Hills inland. Invented here: the plan, the Prince's palace and its orange terraces, every building shape and the harbour layout.",zh:"\u51FA\u81EA\u5C0F\u8BF4\uFF1A\u65B9\u5F62\u7816\u5854\u3001\u4F0A\u5229\u91CC\u6B27\u5E9C\u90B8\u90A3\u6837\u7684\u56F4\u5899\u5B85\u9662\u3001\u7EA2\u888D\u50E7\u4E0E\u591C\u95F4\u5723\u706B\u3001\u4ECE\u53E4\u8001\u5BB6\u65CF\u4E2D\u63A8\u9009\u7684\u4EB2\u738B\u3002\u51FA\u81EA\u300A\u51B0\u4E0E\u706B\u4E4B\u6B4C\uFF1A\u4E16\u754C\u300B\u53CA\u7EF4\u57FA\u6458\u8981\uFF1A\u57CE\u5899\u9AD8\u5927\u5374\u4E0D\u5584\u9632\u5B88\u3001\u4E1C\u9762\u7684\u65E5\u51FA\u95E8\u3001\u96C6\u5E02\u3001\u5185\u9646\u7684\u5929\u9E45\u7ED2\u4E18\u9675\u3002\u672C\u573A\u666F\u81EA\u62DF\uFF1A\u57CE\u5E02\u5E03\u5C40\u3001\u4EB2\u738B\u5BAB\u53CA\u5176\u6A58\u6811\u53F0\u5730\u3001\u6240\u6709\u5EFA\u7B51\u9020\u578B\u4E0E\u6E2F\u53E3\u683C\u5C40\u3002"},tour:["harbour","walls-and-towers","sunrise-gate","bazaars","red-temple","spice-towers","princes-palace","citrus-terraces","illyrios-manse","velvet-hills"],sources:[{ref:"agot",checked:"memory",note:{en:"The opening Pentos chapters (Illyrio's manse, the brick towers, red priests' night fires, the wedding outside the walls) recalled from memory, not re-read.",zh:"\u5F00\u7BC7\u7684\u6F58\u6258\u65AF\u7AE0\u8282\uFF08\u4F0A\u5229\u91CC\u6B27\u5E9C\u90B8\u3001\u7816\u5854\u3001\u7EA2\u888D\u50E7\u7684\u591C\u706B\u3001\u57CE\u5916\u5A5A\u793C\uFF09\u51ED\u8BB0\u5FC6\u590D\u8FF0\uFF0C\u672A\u91CD\u8BFB\u539F\u6587\u3002"}},{ref:"awoiaf",checked:"search-snippet",note:{en:"Walls, square brick towers, the Sunrise Gate, a Prince chosen from forty families, and Illyrio's manse (inside the city, twelve-foot brick walls, a statue of his youthful self) from web-search summaries; pages not fetched. Nothing found on a Prince's palace or orange trees.",zh:"\u57CE\u5899\u3001\u65B9\u5F62\u7816\u5854\u3001\u65E5\u51FA\u95E8\u3001\u4EB2\u738B\u51FA\u81EA\u56DB\u5341\u5BB6\u65CF\uFF0C\u4EE5\u53CA\u4F0A\u5229\u91CC\u6B27\u5E9C\u90B8\uFF08\u4F4D\u4E8E\u57CE\u5185\uFF0C\u5341\u4E8C\u5C3A\u7816\u5899\uFF0C\u5EAD\u4E2D\u6709\u5176\u5C11\u5E74\u96D5\u50CF\uFF09\uFF1A\u636E\u7F51\u7EDC\u641C\u7D22\u6458\u8981\uFF0C\u672A\u80FD\u6253\u5F00\u9875\u9762\u3002\u672A\u627E\u5230\u5173\u4E8E\u4EB2\u738B\u5BAB\u6216\u6A58\u6811\u7684\u8BB0\u8F7D\u3002"}},{ref:"twoiaf",checked:"search-snippet",note:{en:"Pentos on the Bay of Pentos, with flatlands and the Velvet Hills to the east: search summary only.",zh:"\u6F58\u6258\u65AF\u4F4D\u4E8E\u6F58\u6258\u65AF\u6E7E\uFF0C\u4E1C\u6709\u5E73\u539F\u4E0E\u5929\u9E45\u7ED2\u4E18\u9675\uFF1A\u4EC5\u636E\u641C\u7D22\u6458\u8981\u3002"}}],landmarks:{harbour:e({en:"Harbour",zh:"\u6E2F\u53E3"},{en:"Quays and timber piers on the bay, busy with ships crossing the narrow sea.",zh:"\u6D77\u6E7E\u8FB9\u7684\u77F3\u5CB8\u4E0E\u6728\u6808\u6865\uFF0C\u6A2A\u6E21\u72ED\u6D77\u7684\u8239\u53EA\u5F80\u6765\u4E0D\u7EDD\u3002"},{en:"From these piers ships cross the narrow sea to Westeros.",zh:"\u8239\u53EA\u4ECE\u8FD9\u4E9B\u6808\u6865\u542F\u822A\uFF0C\u6A2A\u6E21\u72ED\u6D77\u524D\u5F80\u7EF4\u65AF\u7279\u6D1B\u3002"},{confidence:"medium",refs:["agot","twoiaf"],book:{en:"Pentos is a port on the Bay of Pentos, a short voyage across the narrow sea from Westeros.",zh:"\u6F58\u6258\u65AF\u662F\u6F58\u6258\u65AF\u6E7E\u4E0A\u7684\u6E2F\u53E3\uFF0C\u4E0E\u7EF4\u65AF\u7279\u6D1B\u9694\u72ED\u6D77\u76F8\u671B\uFF0C\u822A\u7A0B\u4E0D\u8FDC\u3002"},unknown:{en:"The real harbour layout, moles and quays.",zh:"\u6E2F\u53E3\u7684\u5B9E\u9645\u5E03\u5C40\u3001\u9632\u6CE2\u5824\u4E0E\u7801\u5934\u3002"},interpretation:{en:"A row of piers along a straight quay, with a small harbour light.",zh:"\u7B14\u76F4\u77F3\u5CB8\u8FB9\u4E00\u6392\u6808\u6865\uFF0C\u5916\u52A0\u4E00\u5EA7\u5C0F\u706F\u5854\u3002"}}),"walls-and-towers":e({en:"Walls and Towers",zh:"\u57CE\u5899\u4E0E\u7816\u5854"},{en:"Massive walls and many square brick towers, yet Pentos is reputed the easiest of the Free Cities to take.",zh:"\u57CE\u5899\u539A\u91CD\uFF0C\u65B9\u5F62\u7816\u5854\u4F17\u591A\uFF0C\u6F58\u6258\u65AF\u5374\u7D20\u6709\u81EA\u7531\u8D38\u6613\u57CE\u90A6\u4E2D\u6700\u6613\u653B\u7834\u4E4B\u540D\u3002"},{en:"High walls and square towers: imposing, yet reputedly the weakest defence among the Free Cities.",zh:"\u9AD8\u5899\u65B9\u5854\u6C14\u52BF\u903C\u4EBA\uFF0C\u9632\u5FA1\u5374\u636E\u8BF4\u662F\u81EA\u7531\u8D38\u6613\u57CE\u90A6\u4E2D\u6700\u5F31\u7684\u3002"},{confidence:"medium",refs:["agot","twoiaf"],book:{en:"Square brick towers appear in the novels; massive walls with a weak defence come from companion summaries.",zh:"\u65B9\u5F62\u7816\u5854\u89C1\u4E8E\u5C0F\u8BF4\uFF1B\u201C\u57CE\u5899\u539A\u91CD\u800C\u9632\u5FA1\u8584\u5F31\u201D\u4E00\u8BF4\u51FA\u81EA\u8BBE\u5B9A\u96C6\u6458\u8981\u3002"},unknown:{en:"The wall's exact circuit, height and number of towers.",zh:"\u57CE\u5899\u7684\u786E\u5207\u8D70\u5411\u3001\u9AD8\u5EA6\u4E0E\u5854\u697C\u6570\u76EE\u3002"},interpretation:{en:"A half-ellipse of brick wall from shore to shore, with evenly spaced square towers.",zh:"\u4ECE\u6D77\u5CB8\u7ED5\u56DE\u6D77\u5CB8\u7684\u534A\u692D\u5706\u5F62\u7816\u5899\uFF0C\u65B9\u5854\u7B49\u8DDD\u6392\u5217\u3002"}}),"sunrise-gate":e({en:"Sunrise Gate",zh:"\u65E5\u51FA\u95E8"},{en:"The eastern gate, where the road leaves the city toward the Rhoyne.",zh:"\u4E1C\u57CE\u95E8\uFF0C\u5927\u9053\u7531\u6B64\u51FA\u57CE\uFF0C\u901A\u5F80\u6D1B\u6069\u6CB3\u65B9\u5411\u3002"},{en:"Leave by the Sunrise Gate and the road runs east, toward the Rhoyne.",zh:"\u51FA\u65E5\u51FA\u95E8\uFF0C\u5927\u9053\u4E00\u8DEF\u5411\u4E1C\uFF0C\u901A\u5F80\u6D1B\u6069\u6CB3\u3002"},{confidence:"medium",refs:["awoiaf"],book:{en:"A wiki summary: the Sunrise Gate lets travellers leave the city eastward, toward the Rhoyne.",zh:"\u636E\u7EF4\u57FA\u6458\u8981\uFF1A\u65C5\u4EBA\u53EF\u7ECF\u65E5\u51FA\u95E8\u5411\u4E1C\u51FA\u57CE\uFF0C\u524D\u5F80\u6D1B\u6069\u6CB3\u4E00\u5E26\u3002"},unknown:{en:"Its form and fortifications.",zh:"\u5F62\u5236\u4E0E\u9632\u5FA1\u5DE5\u4E8B\u3002"},interpretation:{en:"A twin-towered gatehouse on the east wall, with bonfires.",zh:"\u4E1C\u5899\u4E0A\u7684\u53CC\u5854\u95E8\u697C\uFF0C\u71C3\u7740\u7BDD\u706B\u3002"}}),bazaars:e({en:"Bazaars",zh:"\u96C6\u5E02"},{en:"Teeming market streets where traders and servants jostle among the stalls.",zh:"\u7199\u7199\u6518\u6518\u7684\u5E02\u8857\uFF0C\u5546\u8D29\u4E0E\u4EC6\u5F79\u5728\u644A\u4F4D\u95F4\u7A7F\u884C\u3002"},{en:"In Pentos wealth is power, and the bazaars are where it changes hands.",zh:"\u5728\u6F58\u6258\u65AF\uFF0C\u8D22\u5BCC\u5C31\u662F\u6743\u529B\uFF0C\u800C\u96C6\u5E02\u6B63\u662F\u8D22\u5BCC\u6613\u624B\u4E4B\u5904\u3002"},{confidence:"low",refs:["twoiaf"],book:{en:"Teeming bazaars are mentioned only in a search summary.",zh:"\u7199\u6518\u7684\u96C6\u5E02\u4EC5\u89C1\u4E8E\u641C\u7D22\u6458\u8981\u3002"},unknown:{en:"Where they are and what they look like.",zh:"\u4F4D\u7F6E\u4E0E\u6837\u8C8C\u3002"},interpretation:{en:"Awninged stalls lining the main avenue.",zh:"\u4E3B\u8857\u4E24\u4FA7\u642D\u7740\u7BF7\u5E03\u7684\u644A\u4F4D\u3002"}}),"red-temple":e({en:"Red Temple",zh:"\u7EA2\u795E\u5E99"},{en:"A temple of the Lord of Light, where red priests sing and light their night fires.",zh:"\u5149\u4E4B\u738B\u7684\u795E\u5E99\uFF0C\u7EA2\u888D\u50E7\u5728\u6B64\u541F\u5531\uFF0C\u5165\u591C\u70B9\u8D77\u5723\u706B\u3002"},{en:"At dusk the red priests sing and light their fires.",zh:"\u9EC4\u660F\u65F6\u5206\uFF0C\u7EA2\u888D\u50E7\u541F\u5531\u7740\u70B9\u71C3\u5723\u706B\u3002"},{confidence:"medium",refs:["agot","awoiaf"],book:{en:"Red priests are heard lighting their night fires in Pentos; a wiki summary describes a large red temple.",zh:"\u4E66\u4E2D\u5199\u5230\u6F58\u6258\u65AF\u7684\u7EA2\u888D\u50E7\u591C\u95F4\u70B9\u706B\uFF1B\u7EF4\u57FA\u6458\u8981\u63D0\u5230\u4E00\u5EA7\u5927\u578B\u7EA2\u795E\u5E99\u3002"},unknown:{en:"Its shape and position.",zh:"\u5916\u5F62\u4E0E\u4F4D\u7F6E\u3002"},interpretation:{en:"A red-plastered hall with a gilded dome, four slim towers and braziers.",zh:"\u7EA2\u8272\u7C89\u5899\u5927\u6BBF\uFF0C\u9540\u91D1\u7A79\u9876\uFF0C\u56DB\u5EA7\u7EC6\u5854\u4E0E\u706B\u76C6\u3002"}}),"spice-towers":e({en:"Brick Towers",zh:"\u65B9\u5F62\u7816\u5854"},{en:"Tall square brick towers rise above the rooftops; here they are imagined as the towers of rich merchant houses.",zh:"\u9AD8\u8038\u7684\u65B9\u5F62\u7816\u5854\u63A2\u51FA\u5C4B\u9876\u4E4B\u4E0A\uFF1B\u672C\u573A\u666F\u8BBE\u60F3\u5B83\u4EEC\u5C5E\u4E8E\u5BCC\u5546\u4E4B\u5BB6\u3002"},{en:"Square brick towers: the merchants' marks on the skyline.",zh:"\u65B9\u5F62\u7816\u5854\uFF0C\u662F\u5546\u4EBA\u4EEC\u523B\u5728\u5929\u9645\u7EBF\u4E0A\u7684\u5370\u8BB0\u3002"},{confidence:"medium",refs:["agot","awoiaf"],book:{en:"Many square brick towers are established; who owns them is not.",zh:"\u57CE\u4E2D\u591A\u65B9\u5F62\u7816\u5854\uFF0C\u6B64\u70B9\u6709\u636E\uFF1B\u5854\u7684\u5F52\u5C5E\u5219\u65E0\u8BB0\u8F7D\u3002"},unknown:{en:"Which towers belong to whom, and what they are used for.",zh:"\u5404\u5854\u5F52\u8C01\u6240\u6709\u3001\u4F5C\u4F55\u7528\u9014\u3002"},interpretation:{en:'Six taller towers scattered across the city; the scene id "spice-towers" is a label, not a book name.',zh:"\u57CE\u4E2D\u6563\u5E03\u516D\u5EA7\u8F83\u9AD8\u7684\u7816\u5854\uFF1B\u573A\u666F\u7F16\u53F7\u4E2D\u7684\u201C\u9999\u6599\u5854\u201D\u53EA\u662F\u6807\u7B7E\uFF0C\u5E76\u975E\u4E66\u4E2D\u540D\u79F0\u3002"}}),"princes-palace":e({en:"Prince's Palace",zh:"\u4EB2\u738B\u5BAB"},{en:"The Prince, chosen from the old families, presides over feasts and ceremonies; this hilltop palace is imagined for him.",zh:"\u4EB2\u738B\u4ECE\u53E4\u8001\u5BB6\u65CF\u4E2D\u63A8\u9009\uFF0C\u4E3B\u6301\u5BB4\u4F1A\u4E0E\u5178\u793C\uFF1B\u8FD9\u5EA7\u5C71\u9876\u5BAB\u6BBF\u662F\u4E3A\u4ED6\u8BBE\u60F3\u7684\u3002"},{en:"A ceremonial Prince in a hilltop palace; the magisters hold the real power.",zh:"\u5C71\u9876\u5BAB\u4E2D\u5750\u7740\u793C\u4EEA\u6027\u7684\u4EB2\u738B\uFF0C\u5B9E\u6743\u5374\u5728\u603B\u7763\u4EEC\u624B\u91CC\u3002"},{confidence:"low",refs:["agot","awoiaf"],book:{en:"The Prince of Pentos is chosen from the old families and is largely ceremonial; the magisters rule.",zh:"\u6F58\u6258\u65AF\u4EB2\u738B\u4ECE\u53E4\u8001\u5BB6\u65CF\u4E2D\u63A8\u9009\uFF0C\u591A\u53F8\u793C\u4EEA\uFF1B\u771F\u6B63\u7EDF\u6CBB\u7684\u662F\u603B\u7763\u4EEC\u3002"},unknown:{en:"Any description of his residence: none found in the sources checked.",zh:"\u5176\u5C45\u6240\u7684\u4EFB\u4F55\u63CF\u5199\uFF1A\u6240\u67E5\u8D44\u6599\u4E2D\u5747\u672A\u89C1\u5230\u3002"},interpretation:{en:"A hilltop palace with a gilt dome, towers and terraces; entirely invented.",zh:"\u91D1\u9876\u3001\u5854\u697C\u4E0E\u53F0\u5730\u4FF1\u5168\u7684\u5C71\u9876\u5BAB\u6BBF\uFF1B\u5B8C\u5168\u81EA\u62DF\u3002"}}),"citrus-terraces":e({en:"Citrus Terraces",zh:"\u6A58\u6811\u53F0\u5730"},{en:"Terraced gardens of orange trees below the palace, a warm-climate touch.",zh:"\u5BAB\u6BBF\u4E0B\u65B9\u7684\u6A58\u6811\u53F0\u5730\u82B1\u56ED\uFF0C\u6DFB\u4E00\u5206\u6696\u5730\u98CE\u60C5\u3002"},{en:"Orange trees on terraces: a pleasant guess, not a quotation.",zh:"\u53F0\u5730\u4E0A\u7684\u6A58\u6811\uFF1A\u5408\u4E4E\u60C5\u7406\u7684\u60F3\u8C61\uFF0C\u5E76\u975E\u539F\u8457\u63CF\u5199\u3002"},{confidence:"low",refs:["awoiaf"],book:{en:"No orange groves in Pentos were found in the sources checked.",zh:"\u6240\u67E5\u8D44\u6599\u4E2D\u672A\u89C1\u6F58\u6258\u65AF\u6709\u6A58\u56ED\u7684\u8BB0\u8F7D\u3002"},unknown:{en:"Whether such gardens are described at all.",zh:"\u4E66\u4E2D\u662F\u5426\u5199\u8FC7\u6B64\u7C7B\u56ED\u6797\u3002"},interpretation:{en:"Fruit-laden trees on terraces around the palace; purely decorative.",zh:"\u5BAB\u6BBF\u5468\u56F4\u53F0\u5730\u4E0A\u6302\u6EE1\u679C\u5B9E\u7684\u6811\uFF1B\u7EAF\u5C5E\u88C5\u9970\u3002"}}),"illyrios-manse":e({en:"Illyrio's Manse",zh:"\u4F0A\u5229\u91CC\u6B27\u5E9C\u90B8"},{en:"The walled manse of Magister Illyrio Mopatis, where two Targaryen exiles live as his guests.",zh:"\u603B\u7763\u4F0A\u5229\u91CC\u6B27\xB7\u83AB\u5E15\u63D0\u65AF\u7684\u56F4\u5899\u5E9C\u90B8\uFF0C\u4E24\u4F4D\u6D41\u4EA1\u7684\u5766\u683C\u5229\u5B89\u540E\u88D4\u5BC4\u5C45\u4E8E\u6B64\u3002"},{en:"Behind these walls a magister shelters two exiles and arranges a marriage.",zh:"\u9AD8\u5899\u4E4B\u5185\uFF0C\u4E00\u4F4D\u603B\u7763\u6536\u7559\u4E86\u4E24\u540D\u6D41\u4EA1\u8005\uFF0C\u5E76\u4FC3\u6210\u4E00\u6869\u5A5A\u4E8B\u3002"},{confidence:"high",refs:["agot","awoiaf"],book:{en:"Illyrio Mopatis hosts Viserys and Daenerys in his manse and arranges her marriage to Khal Drogo; the wedding itself is held in a field outside the city walls.",zh:"\u4F0A\u5229\u91CC\u6B27\xB7\u83AB\u5E15\u63D0\u65AF\u5728\u5E9C\u4E2D\u6B3E\u5F85\u97E6\u8D5B\u91CC\u65AF\u4E0E\u4E39\u59AE\u8389\u4E1D\uFF0C\u5E76\u4FC3\u6210\u5979\u4E0E\u5353\u6208\u5361\u5965\u7684\u5A5A\u4E8B\uFF1B\u5A5A\u793C\u672C\u8EAB\u5728\u57CE\u5899\u5916\u7684\u539F\u91CE\u4E0A\u4E3E\u884C\u3002"},unknown:{en:"Its exact location and size.",zh:"\u786E\u5207\u4F4D\u7F6E\u4E0E\u89C4\u6A21\u3002"},interpretation:{en:"Placed on a hill outside the walls to the north-east, with a gatehouse and fountain court; wiki summaries put the manse inside the city.",zh:"\u672C\u573A\u666F\u5C06\u5176\u7F6E\u4E8E\u57CE\u5916\u4E1C\u5317\u7684\u5C71\u4E18\uFF0C\u8BBE\u95E8\u697C\u4E0E\u55B7\u6CC9\u5EAD\u9662\uFF1B\u800C\u7EF4\u57FA\u6458\u8981\u79F0\u5E9C\u90B8\u4F4D\u4E8E\u57CE\u5185\u3002"}},{en:"In A Dance with Dragons Tyrion is sheltered here; its court holds a marble statue of Illyrio as a youthful bravo.",zh:"\u300A\u9B54\u9F99\u7684\u72C2\u821E\u300B\u4E2D\uFF0C\u63D0\u5229\u6602\u66FE\u85CF\u8EAB\u4E8E\u6B64\uFF1B\u5EAD\u9662\u91CC\u7ACB\u7740\u4F0A\u5229\u91CC\u6B27\u5C11\u5E74\u65F6\u4F5C\u5251\u5BA2\u6253\u626E\u7684\u5927\u7406\u77F3\u50CF\u3002"}),"velvet-hills":e({en:"Velvet Hills",zh:"\u5929\u9E45\u7ED2\u4E18\u9675"},{en:"Low rolling hills and farmland east of the city, hazy in the distance.",zh:"\u57CE\u4E1C\u4F4E\u7F13\u8D77\u4F0F\u7684\u4E18\u9675\u4E0E\u519C\u7530\uFF0C\u8FDC\u5904\u7B3C\u7740\u8584\u96FE\u3002"},{en:"East of the gate lie farms and the soft Velvet Hills.",zh:"\u57CE\u95E8\u4EE5\u4E1C\uFF0C\u662F\u519C\u7530\u548C\u67D4\u7F13\u7684\u5929\u9E45\u7ED2\u4E18\u9675\u3002"},{confidence:"medium",refs:["twoiaf","adwd"],book:{en:"The Velvet Hills are low hills east of Pentos (search summary).",zh:"\u5929\u9E45\u7ED2\u4E18\u9675\u662F\u6F58\u6258\u65AF\u4EE5\u4E1C\u7684\u4E00\u7247\u4F4E\u4E18\uFF08\u636E\u641C\u7D22\u6458\u8981\uFF09\u3002"},unknown:{en:"Their size and exact distance from the city.",zh:"\u8303\u56F4\u4E0E\u8DDD\u57CE\u7684\u786E\u5207\u91CC\u7A0B\u3002"},interpretation:{en:"A tan, gently rising range with scattered fields and olive groves.",zh:"\u6D45\u8910\u8272\u7684\u7F13\u5761\u5C71\u5730\uFF0C\u7530\u7574\u4E0E\u6A44\u6984\u6797\u6563\u843D\u5176\u95F4\u3002"}})}};export{o as default};
